import React, { useEffect, useMemo, useState } from "react";
import { BarChart3, Crown, FileText, FolderKanban, Loader2, MessageSquare, Save, Search, Send, ShieldCheck, Users } from "lucide-react";
import { supabase, PORTAL_STORAGE_BUCKETS } from "../lib/supabase";

const fieldClass = "w-full rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-slate-950 px-4 py-3 text-sm text-slate-800 dark:text-white outline-none focus:border-indigo-500";
const buttonClass = "inline-flex items-center justify-center gap-2 rounded-xl bg-indigo-600 px-5 py-3 text-sm font-semibold text-white transition hover:bg-indigo-500 disabled:opacity-60";
const label = (value = "") => String(value).replaceAll("_", " ").replace(/\b\w/g, (m) => m.toUpperCase());
const cleanFileName = (value = "file") => value.replace(/[^a-zA-Z0-9._-]+/g, "-").replace(/-+/g, "-");

function Card({ title, text, icon: Icon, children }) {
  return <section className="rounded-2xl border border-slate-200 dark:border-white/10 bg-white dark:bg-slate-900 p-6"><div className="flex items-start gap-3"><div className="h-10 w-10 rounded-xl bg-indigo-50 dark:bg-indigo-500/10 text-indigo-600 dark:text-indigo-300 flex items-center justify-center"><Icon size={20}/></div><div><h3 className="font-bold text-slate-950 dark:text-white">{title}</h3>{text&&<p className="mt-1 text-sm text-slate-500 dark:text-slate-400">{text}</p>}</div></div><div className="mt-5">{children}</div></section>;
}

export default function PortalAdminExtras({ session, mode = "admin", onRefresh }) {
  const isAdmin = mode === "admin";
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState("");
  const [message, setMessage] = useState("");
  const [search, setSearch] = useState("");
  const [orgs, setOrgs] = useState([]);
  const [profiles, setProfiles] = useState([]);
  const [memberships, setMemberships] = useState([]);
  const [projects, setProjects] = useState([]);
  const [milestones, setMilestones] = useState([]);
  const [invoices, setInvoices] = useState([]);
  const [tickets, setTickets] = useState([]);
  const [supportMessages, setSupportMessages] = useState([]);
  const [orgEdit, setOrgEdit] = useState({ id:"", name:"", contact_name:"", contact_email:"", contact_phone:"", logo_url:"", website_url:"", client_number:"", is_founder:false, badge_title:"", badge_note:"", status:"active" });
  const [projectEdit, setProjectEdit] = useState({ id:"", name:"", summary:"", service_division:"", received_date:"", start_date:"", due_date:"", completed_at:"", status:"planning", progress:"0", client_visible:true });
  const [milestoneForm, setMilestoneForm] = useState({ project_id:"", title:"", description:"", status:"not_started", due_date:"", sort_order:"0" });
  const [invoiceEdit, setInvoiceEdit] = useState({ id:"", status:"issued", amount_paid:"0", due_date:"" });
  const [selectedTicketId, setSelectedTicketId] = useState("");
  const [supportReply, setSupportReply] = useState("");
  const [supportInternal, setSupportInternal] = useState(false);
  const [noticeForm, setNoticeForm] = useState({ organization_id:"", title:"", body:"" });
  const [staffProject, setStaffProject] = useState({ organization_id:"", code:"", name:"", summary:"", service_division:"", received_date:"", start_date:"", due_date:"" });
  const [staffUpdate, setStaffUpdate] = useState({ project_id:"", title:"", body:"", update_type:"general" });
  const [staffDocument, setStaffDocument] = useState({ organization_id:"", project_id:"", title:"", category:"general", file:null });

  const load = async () => {
    setLoading(true);
    const [a,b,c,d,e,f,g,h] = await Promise.all([
      supabase.from("client_organizations").select("id,name,status,primary_contact_name,primary_contact_email,primary_contact_phone,logo_url,website_url,client_number,is_founder,badge_title,badge_note").order("client_number",{ascending:true,nullsFirst:false}),
      supabase.from("profiles").select("id,full_name,email,role,status,phone,job_title").order("created_at",{ascending:false}),
      supabase.from("organization_members").select("id,organization_id,user_id,member_role,status").eq("status","active"),
      supabase.from("projects").select("id,organization_id,code,name,summary,service_division,status,progress,received_date,start_date,due_date,completed_at,client_visible").order("created_at",{ascending:false}),
      supabase.from("project_milestones").select("id,project_id,organization_id,title,description,status,due_date,completed_at,sort_order,client_visible").order("sort_order",{ascending:true}),
      supabase.from("invoices").select("id,organization_id,project_id,invoice_number,amount,amount_paid,status,due_date").order("created_at",{ascending:false}),
      supabase.from("support_tickets").select("id,organization_id,project_id,ticket_number,subject,description,priority,status,created_by,assigned_to,created_at").order("created_at",{ascending:false}),
      supabase.from("support_messages").select("id,ticket_id,organization_id,sender_id,message,is_internal,created_at").order("created_at",{ascending:true}),
    ]);
    const err=[a,b,c,d,e,f,g,h].find(x=>x.error)?.error;
    if(err) setMessage(err.message);
    setOrgs(a.data||[]); setProfiles(b.data||[]); setMemberships(c.data||[]); setProjects(d.data||[]); setMilestones(e.data||[]); setInvoices(f.data||[]); setTickets(g.data||[]); setSupportMessages(h.data||[]); setSelectedTicketId((v)=>v||g.data?.[0]?.id||""); setLoading(false);
  };
  useEffect(()=>{load();},[]);

  const orgMap=useMemo(()=>Object.fromEntries(orgs.map(o=>[o.id,o])),[orgs]);
  const projectMap=useMemo(()=>Object.fromEntries(projects.map(p=>[p.id,p])),[projects]);
  const profileMap=useMemo(()=>Object.fromEntries(profiles.map(p=>[p.id,p])),[profiles]);
  const selectedTicket=tickets.find(t=>t.id===selectedTicketId);
  const ticketMessages=supportMessages.filter(m=>m.ticket_id===selectedTicketId);
  const q=search.trim().toLowerCase();
  const shownOrgs=orgs.filter(o=>!q||[o.name,o.primary_contact_name,o.primary_contact_email,o.badge_title].some(v=>String(v||"").toLowerCase().includes(q)));
  const shownProjects=projects.filter(p=>!q||[p.code,p.name,p.summary,orgMap[p.organization_id]?.name].some(v=>String(v||"").toLowerCase().includes(q)));

  const run=async(key,fn,ok)=>{setBusy(key);setMessage("");try{await fn();setMessage(ok);await load();onRefresh?.();}catch(e){setMessage(e?.message||"The action could not be completed.");}finally{setBusy("");}};

  const chooseOrg=(id)=>{const o=orgMap[id];if(!o){setOrgEdit({...orgEdit,id:""});return;}setOrgEdit({id:o.id,name:o.name||"",contact_name:o.primary_contact_name||"",contact_email:o.primary_contact_email||"",contact_phone:o.primary_contact_phone||"",logo_url:o.logo_url||"",website_url:o.website_url||"",client_number:o.client_number??"",is_founder:!!o.is_founder,badge_title:o.badge_title||"",badge_note:o.badge_note||"",status:o.status||"active"});};
  const saveOrg=(e)=>{e.preventDefault();run("org",async()=>{const {error}=await supabase.from("client_organizations").update({name:orgEdit.name.trim(),primary_contact_name:orgEdit.contact_name.trim()||null,primary_contact_email:orgEdit.contact_email.trim().toLowerCase()||null,primary_contact_phone:orgEdit.contact_phone.trim()||null,logo_url:orgEdit.logo_url.trim()||null,website_url:orgEdit.website_url.trim()||null,client_number:orgEdit.client_number===""?null:Number(orgEdit.client_number),is_founder:orgEdit.is_founder,badge_title:orgEdit.badge_title.trim()||null,badge_note:orgEdit.badge_note.trim()||null,status:orgEdit.status}).eq("id",orgEdit.id);if(error)throw error;},"Client organisation updated.");};

  const chooseProject=(id)=>{const p=projectMap[id];if(!p){setProjectEdit({...projectEdit,id:""});return;}setProjectEdit({id:p.id,name:p.name||"",summary:p.summary||"",service_division:p.service_division||"",received_date:p.received_date||"",start_date:p.start_date||"",due_date:p.due_date||"",completed_at:p.completed_at?String(p.completed_at).slice(0,10):"",status:p.status||"planning",progress:String(p.progress??0),client_visible:p.client_visible!==false});};
  const saveProject=(e)=>{e.preventDefault();run("project",async()=>{const {error}=await supabase.from("projects").update({name:projectEdit.name.trim(),summary:projectEdit.summary.trim()||null,service_division:projectEdit.service_division.trim()||null,received_date:projectEdit.received_date||null,start_date:projectEdit.start_date||null,due_date:projectEdit.due_date||null,completed_at:projectEdit.completed_at?`${projectEdit.completed_at}T00:00:00Z`:null,status:projectEdit.status,progress:Math.max(0,Math.min(100,Number(projectEdit.progress||0))),client_visible:projectEdit.client_visible}).eq("id",projectEdit.id);if(error)throw error;},"Project updated.");};

  const addMilestone=(e)=>{e.preventDefault();run("milestone",async()=>{const p=projectMap[milestoneForm.project_id];if(!p)throw new Error("Select a project.");const {error}=await supabase.from("project_milestones").insert({project_id:p.id,organization_id:p.organization_id,title:milestoneForm.title.trim(),description:milestoneForm.description.trim()||null,status:milestoneForm.status,due_date:milestoneForm.due_date||null,sort_order:Number(milestoneForm.sort_order||0),client_visible:true});if(error)throw error;setMilestoneForm({...milestoneForm,title:"",description:"",due_date:"",sort_order:String(Number(milestoneForm.sort_order||0)+1)});},"Milestone added.");};
  const setMilestoneStatus=(id,status)=>run(`m-${id}`,async()=>{const {error}=await supabase.from("project_milestones").update({status,completed_at:status==="completed"?new Date().toISOString():null}).eq("id",id);if(error)throw error;},"Milestone updated.");

  const chooseInvoice=(id)=>{const x=invoices.find(i=>i.id===id);setInvoiceEdit(x?{id:x.id,status:x.status,amount_paid:String(x.amount_paid||0),due_date:x.due_date||""}:{id:"",status:"issued",amount_paid:"0",due_date:""});};
  const saveInvoice=(e)=>{e.preventDefault();run("invoice",async()=>{const {error}=await supabase.from("invoices").update({status:invoiceEdit.status,amount_paid:Number(invoiceEdit.amount_paid||0),due_date:invoiceEdit.due_date||null}).eq("id",invoiceEdit.id);if(error)throw error;},"Invoice updated and client notified.");};

  const updateUser=(id,patch)=>run(`u-${id}`,async()=>{const current=profileMap[id];if(!current)throw new Error("Portal user not found.");const {data,error}=await supabase.functions.invoke("admin-portal-action",{body:{action:"manage_user",user_id:id,role:patch.role||current.role,status:patch.status||current.status}});if(error)throw error;if(data?.error)throw new Error(data.error);},"User access updated securely.");
  const sendNotice=(e)=>{e.preventDefault();run("notice",async()=>{const ids=memberships.filter(m=>m.organization_id===noticeForm.organization_id&&m.status==="active").map(m=>m.user_id);if(!ids.length)throw new Error("This organisation has no active portal users.");const {error}=await supabase.from("notifications").insert(ids.map(user_id=>({user_id,title:noticeForm.title.trim(),body:noticeForm.body.trim()||null,link:"/portal/"})));if(error)throw error;setNoticeForm({...noticeForm,title:"",body:""});},"Client notification sent.");};

  const setTicketStatus=(status)=>run("ticket-status",async()=>{const {error}=await supabase.from("support_tickets").update({status,assigned_to:session.user.id,closed_at:["resolved","closed"].includes(status)?new Date().toISOString():null}).eq("id",selectedTicket.id);if(error)throw error;},"Support ticket updated.");
  const sendSupport=(e)=>{e.preventDefault();run("support",async()=>{const {error}=await supabase.from("support_messages").insert({ticket_id:selectedTicket.id,organization_id:selectedTicket.organization_id,sender_id:session.user.id,message:supportReply.trim(),is_internal:supportInternal});if(error)throw error;setSupportReply("");setSupportInternal(false);},supportInternal?"Internal note saved.":"Reply sent to client.");};

  const createStaffProject=(e)=>{e.preventDefault();run("staff-project",async()=>{const {error}=await supabase.from("projects").insert({organization_id:staffProject.organization_id,code:staffProject.code.trim().toUpperCase(),name:staffProject.name.trim(),summary:staffProject.summary.trim()||null,service_division:staffProject.service_division.trim()||null,received_date:staffProject.received_date||null,start_date:staffProject.start_date||null,due_date:staffProject.due_date||null,status:"planning",progress:0,client_visible:true,created_by:session.user.id});if(error)throw error;setStaffProject({...staffProject,code:"",name:"",summary:"",service_division:"",received_date:"",start_date:"",due_date:""});},"Project created.");};
  const postStaffUpdate=(e)=>{e.preventDefault();run("staff-update",async()=>{const p=projectMap[staffUpdate.project_id];const {error}=await supabase.from("project_updates").insert({project_id:p.id,organization_id:p.organization_id,title:staffUpdate.title.trim(),body:staffUpdate.body.trim(),update_type:staffUpdate.update_type,client_visible:true,created_by:session.user.id});if(error)throw error;setStaffUpdate({...staffUpdate,title:"",body:""});},"Project update published and client notified.");};
  const uploadStaffDoc=(e)=>{e.preventDefault();run("staff-doc",async()=>{if(!staffDocument.file)throw new Error("Choose a file.");const path=`${staffDocument.organization_id}/${staffDocument.project_id||"general"}/${Date.now()}-${cleanFileName(staffDocument.file.name)}`;const {error:up}=await supabase.storage.from(PORTAL_STORAGE_BUCKETS.documents).upload(path,staffDocument.file,{contentType:staffDocument.file.type||undefined});if(up)throw up;const {error}=await supabase.from("documents").insert({organization_id:staffDocument.organization_id,project_id:staffDocument.project_id||null,title:staffDocument.title.trim()||staffDocument.file.name,category:staffDocument.category,storage_bucket:PORTAL_STORAGE_BUCKETS.documents,storage_path:path,file_name:staffDocument.file.name,mime_type:staffDocument.file.type||null,size_bytes:staffDocument.file.size,client_visible:true,uploaded_by:session.user.id});if(error)throw error;setStaffDocument({...staffDocument,title:"",file:null});},"Document uploaded.");};

  if(loading)return <div className="rounded-2xl border border-slate-200 dark:border-white/10 bg-white dark:bg-slate-900 p-8 flex items-center justify-center gap-3"><Loader2 className="animate-spin" size={20}/> Loading workspace…</div>;

  return <div className="mt-6 space-y-6">
    <div className="rounded-2xl border border-indigo-200 dark:border-indigo-500/20 bg-indigo-50 dark:bg-indigo-500/10 p-5"><div className="flex items-center gap-2 text-indigo-700 dark:text-indigo-200"><ShieldCheck size={18}/><span className="text-xs font-bold uppercase tracking-[0.14em]">{isAdmin?"Advanced administrator controls":"Staff operations"}</span></div><p className="mt-2 text-sm text-slate-600 dark:text-slate-300">Editing, milestones, payments, support conversations and access controls are available here.</p></div>
    {message&&<div className="rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-slate-900 px-4 py-3 text-sm text-slate-600 dark:text-slate-300">{message}</div>}
    {orgs.filter(o=>o.is_founder).map(o=><div key={`founder-${o.id}`} className="rounded-2xl border border-amber-200 dark:border-amber-500/20 bg-gradient-to-r from-amber-50 to-white dark:from-amber-500/10 dark:to-slate-900 p-5"><div className="flex items-center gap-4">{o.logo_url?<img src={o.logo_url} alt={`${o.name} logo`} className="h-14 w-14 rounded-xl border border-amber-200 bg-white object-contain p-2"/>:<div className="h-14 w-14 rounded-xl bg-amber-100 text-amber-700 flex items-center justify-center"><Crown size={24}/></div>}<div><p className="text-xs font-bold uppercase tracking-[0.14em] text-amber-700 dark:text-amber-300">Founding client history</p><h3 className="mt-1 text-lg font-bold text-slate-950 dark:text-white">{o.badge_title || `Client ${String(o.client_number||1).padStart(3,"0")} · ${o.name}`}</h3><p className="mt-1 text-sm text-slate-600 dark:text-slate-300">{o.badge_note || `${o.name} is recognised as an early Eragonova client.`}</p></div></div></div>)}
    <div className="relative"><Search size={17} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"/><input className={`${fieldClass} pl-11`} value={search} onChange={(e)=>setSearch(e.target.value)} placeholder="Search clients, contacts, projects or codes…"/></div>

    {isAdmin&&<Card title="Edit client organisation" text="Manage branding, status and permanent client distinctions." icon={Crown}><form onSubmit={saveOrg} className="grid sm:grid-cols-2 xl:grid-cols-4 gap-3"><select className={`${fieldClass} sm:col-span-2 xl:col-span-4`} value={orgEdit.id} onChange={(e)=>chooseOrg(e.target.value)}><option value="">Select client</option>{shownOrgs.map(o=><option key={o.id} value={o.id}>{o.client_number?`Client ${String(o.client_number).padStart(3,"0")} · `:""}{o.name}</option>)}</select>{orgEdit.id&&<><input className={fieldClass} value={orgEdit.name} onChange={(e)=>setOrgEdit({...orgEdit,name:e.target.value})} placeholder="Name"/><input className={fieldClass} value={orgEdit.contact_name} onChange={(e)=>setOrgEdit({...orgEdit,contact_name:e.target.value})} placeholder="Contact name"/><input type="email" className={fieldClass} value={orgEdit.contact_email} onChange={(e)=>setOrgEdit({...orgEdit,contact_email:e.target.value})} placeholder="Contact email"/><input className={fieldClass} value={orgEdit.contact_phone} onChange={(e)=>setOrgEdit({...orgEdit,contact_phone:e.target.value})} placeholder="Contact phone"/><input className={`${fieldClass} sm:col-span-2`} value={orgEdit.logo_url} onChange={(e)=>setOrgEdit({...orgEdit,logo_url:e.target.value})} placeholder="Logo URL"/><input className={`${fieldClass} sm:col-span-2`} value={orgEdit.website_url} onChange={(e)=>setOrgEdit({...orgEdit,website_url:e.target.value})} placeholder="Website URL"/><input type="number" min="1" className={fieldClass} value={orgEdit.client_number} onChange={(e)=>setOrgEdit({...orgEdit,client_number:e.target.value})} placeholder="Client number"/><select className={fieldClass} value={orgEdit.status} onChange={(e)=>setOrgEdit({...orgEdit,status:e.target.value})}><option value="active">Active</option><option value="inactive">Inactive</option><option value="archived">Archived</option></select><label className="flex items-center gap-2 px-2 text-sm text-slate-600 dark:text-slate-300"><input type="checkbox" checked={orgEdit.is_founder} onChange={(e)=>setOrgEdit({...orgEdit,is_founder:e.target.checked})}/> Founding / special client</label><input className={fieldClass} value={orgEdit.badge_title} onChange={(e)=>setOrgEdit({...orgEdit,badge_title:e.target.value})} placeholder="Badge title"/><textarea className={`${fieldClass} sm:col-span-2 xl:col-span-4`} rows="3" value={orgEdit.badge_note} onChange={(e)=>setOrgEdit({...orgEdit,badge_note:e.target.value})} placeholder="Badge note"/><button disabled={busy==="org"} className={`${buttonClass} sm:col-span-2 xl:col-span-4`}>{busy==="org"?<Loader2 className="animate-spin" size={17}/>:<Save size={17}/>} Save client</button></>}</form></Card>}

    <div className="grid xl:grid-cols-2 gap-6">
      <Card title="Edit project" text="Update dates, progress, status, visibility or archive a project by cancelling it." icon={FolderKanban}><form onSubmit={saveProject} className="grid sm:grid-cols-2 gap-3"><select className={`${fieldClass} sm:col-span-2`} value={projectEdit.id} onChange={(e)=>chooseProject(e.target.value)}><option value="">Select project</option>{shownProjects.map(p=><option key={p.id} value={p.id}>{p.code} — {p.name}</option>)}</select>{projectEdit.id&&<><input className={`${fieldClass} sm:col-span-2`} value={projectEdit.name} onChange={(e)=>setProjectEdit({...projectEdit,name:e.target.value})}/><textarea rows="3" className={`${fieldClass} sm:col-span-2`} value={projectEdit.summary} onChange={(e)=>setProjectEdit({...projectEdit,summary:e.target.value})}/><input className={`${fieldClass} sm:col-span-2`} value={projectEdit.service_division} onChange={(e)=>setProjectEdit({...projectEdit,service_division:e.target.value})} placeholder="Service division"/><select className={fieldClass} value={projectEdit.status} onChange={(e)=>setProjectEdit({...projectEdit,status:e.target.value})}><option value="planning">Planning</option><option value="in_progress">In progress</option><option value="awaiting_client">Awaiting client</option><option value="review">Review</option><option value="on_hold">On hold</option><option value="completed">Completed</option><option value="cancelled">Cancelled / archived</option></select><input type="number" min="0" max="100" className={fieldClass} value={projectEdit.progress} onChange={(e)=>setProjectEdit({...projectEdit,progress:e.target.value})} placeholder="Progress %"/><label className="text-xs text-slate-500">Received<input type="date" className={`${fieldClass} mt-1`} value={projectEdit.received_date} onChange={(e)=>setProjectEdit({...projectEdit,received_date:e.target.value})}/></label><label className="text-xs text-slate-500">Start<input type="date" className={`${fieldClass} mt-1`} value={projectEdit.start_date} onChange={(e)=>setProjectEdit({...projectEdit,start_date:e.target.value})}/></label><label className="text-xs text-slate-500">Due<input type="date" className={`${fieldClass} mt-1`} value={projectEdit.due_date} onChange={(e)=>setProjectEdit({...projectEdit,due_date:e.target.value})}/></label><label className="text-xs text-slate-500">Completed<input type="date" className={`${fieldClass} mt-1`} value={projectEdit.completed_at} onChange={(e)=>setProjectEdit({...projectEdit,completed_at:e.target.value})}/></label><label className="sm:col-span-2 flex items-center gap-2 text-sm text-slate-600 dark:text-slate-300"><input type="checkbox" checked={projectEdit.client_visible} onChange={(e)=>setProjectEdit({...projectEdit,client_visible:e.target.checked})}/> Visible to client</label><button disabled={busy==="project"} className={`${buttonClass} sm:col-span-2`}>Save project</button></>}</form></Card>

      <Card title="Milestones" text="Create and complete delivery checkpoints visible to the client." icon={BarChart3}><form onSubmit={addMilestone} className="space-y-3"><select required className={fieldClass} value={milestoneForm.project_id} onChange={(e)=>setMilestoneForm({...milestoneForm,project_id:e.target.value})}><option value="">Select project</option>{shownProjects.map(p=><option key={p.id} value={p.id}>{p.code} — {p.name}</option>)}</select><input required className={fieldClass} value={milestoneForm.title} onChange={(e)=>setMilestoneForm({...milestoneForm,title:e.target.value})} placeholder="Milestone title"/><textarea rows="2" className={fieldClass} value={milestoneForm.description} onChange={(e)=>setMilestoneForm({...milestoneForm,description:e.target.value})} placeholder="Description"/><div className="grid grid-cols-3 gap-2"><select className={fieldClass} value={milestoneForm.status} onChange={(e)=>setMilestoneForm({...milestoneForm,status:e.target.value})}><option value="not_started">Not started</option><option value="in_progress">In progress</option><option value="awaiting_client">Awaiting client</option><option value="completed">Completed</option><option value="delayed">Delayed</option></select><input type="date" className={fieldClass} value={milestoneForm.due_date} onChange={(e)=>setMilestoneForm({...milestoneForm,due_date:e.target.value})}/><input type="number" className={fieldClass} value={milestoneForm.sort_order} onChange={(e)=>setMilestoneForm({...milestoneForm,sort_order:e.target.value})}/></div><button disabled={busy==="milestone"} className={buttonClass}>Add milestone</button></form><div className="mt-4 space-y-2">{milestones.filter(m=>!milestoneForm.project_id||m.project_id===milestoneForm.project_id).slice(0,12).map(m=><div key={m.id} className="rounded-xl border border-slate-100 dark:border-white/10 p-3 flex items-center justify-between gap-3"><div><p className="text-sm font-semibold text-slate-900 dark:text-white">{m.title}</p><p className="text-[11px] text-slate-400">{projectMap[m.project_id]?.code}</p></div><select value={m.status} onChange={(e)=>setMilestoneStatus(m.id,e.target.value)} className="rounded-lg border border-slate-200 dark:border-white/10 bg-white dark:bg-slate-950 px-2 py-1.5 text-xs"><option value="not_started">Not started</option><option value="in_progress">In progress</option><option value="awaiting_client">Awaiting client</option><option value="completed">Completed</option><option value="delayed">Delayed</option></select></div>)}</div></Card>

      <Card title="Update invoice / payment" text="Record payment progress and invoice status." icon={FileText}><form onSubmit={saveInvoice} className="space-y-3"><select className={fieldClass} value={invoiceEdit.id} onChange={(e)=>chooseInvoice(e.target.value)}><option value="">Select invoice</option>{invoices.map(i=><option key={i.id} value={i.id}>{i.invoice_number} · {orgMap[i.organization_id]?.name||"Client"}</option>)}</select>{invoiceEdit.id&&<><select className={fieldClass} value={invoiceEdit.status} onChange={(e)=>setInvoiceEdit({...invoiceEdit,status:e.target.value})}><option value="draft">Draft</option><option value="issued">Issued</option><option value="part_paid">Part paid</option><option value="paid">Paid</option><option value="overdue">Overdue</option><option value="cancelled">Cancelled</option></select><input type="number" step="0.01" min="0" className={fieldClass} value={invoiceEdit.amount_paid} onChange={(e)=>setInvoiceEdit({...invoiceEdit,amount_paid:e.target.value})} placeholder="Amount paid"/><input type="date" className={fieldClass} value={invoiceEdit.due_date} onChange={(e)=>setInvoiceEdit({...invoiceEdit,due_date:e.target.value})}/><button disabled={busy==="invoice"} className={buttonClass}>Save invoice</button></>}</form></Card>

      {isAdmin&&<Card title="Client notifications" text="Send a portal notification to every active user in a client organisation." icon={Send}><form onSubmit={sendNotice} className="space-y-3"><select required className={fieldClass} value={noticeForm.organization_id} onChange={(e)=>setNoticeForm({...noticeForm,organization_id:e.target.value})}><option value="">Select client</option>{orgs.map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select><input required className={fieldClass} value={noticeForm.title} onChange={(e)=>setNoticeForm({...noticeForm,title:e.target.value})} placeholder="Notification title"/><textarea rows="3" className={fieldClass} value={noticeForm.body} onChange={(e)=>setNoticeForm({...noticeForm,body:e.target.value})} placeholder="Message"/><button disabled={busy==="notice"} className={buttonClass}>Send notification</button></form></Card>}
    </div>

    <Card title="Support conversations" text="Reply to clients, add internal notes and resolve tickets." icon={MessageSquare}><div className="grid xl:grid-cols-[.7fr_1.3fr] gap-5"><div className="space-y-2 max-h-[440px] overflow-y-auto">{tickets.map(t=><button key={t.id} onClick={()=>setSelectedTicketId(t.id)} className={`w-full text-left rounded-xl border p-3 ${selectedTicketId===t.id?"border-indigo-400 bg-indigo-50 dark:bg-indigo-500/10":"border-slate-100 dark:border-white/10"}`}><p className="text-xs font-bold text-indigo-500">{t.ticket_number}</p><p className="mt-1 text-sm font-semibold text-slate-900 dark:text-white">{t.subject}</p><p className="mt-1 text-[11px] text-slate-400">{orgMap[t.organization_id]?.name||"Client"} · {label(t.status)}</p></button>)}</div><div>{selectedTicket?<><div className="flex flex-col sm:flex-row gap-3 justify-between"><div><h4 className="font-bold text-slate-950 dark:text-white">{selectedTicket.subject}</h4><p className="mt-1 text-sm text-slate-500">{selectedTicket.description}</p></div><select className={fieldClass} value={selectedTicket.status} onChange={(e)=>setTicketStatus(e.target.value)}><option value="open">Open</option><option value="in_progress">In progress</option><option value="waiting_on_client">Waiting on client</option><option value="resolved">Resolved</option><option value="closed">Closed</option></select></div><div className="mt-4 space-y-2 max-h-[280px] overflow-y-auto">{ticketMessages.map(m=><div key={m.id} className={`rounded-xl p-3 ${m.is_internal?"bg-amber-50 dark:bg-amber-500/10":"bg-slate-50 dark:bg-white/5"}`}><p className="text-xs font-semibold text-slate-500">{profileMap[m.sender_id]?.full_name||profileMap[m.sender_id]?.email||"User"}{m.is_internal?" · Internal note":""}</p><p className="mt-1 text-sm text-slate-700 dark:text-slate-200">{m.message}</p></div>)}</div><form onSubmit={sendSupport} className="mt-4 space-y-3"><textarea required rows="3" className={fieldClass} value={supportReply} onChange={(e)=>setSupportReply(e.target.value)} placeholder="Reply or internal note"/><label className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-300"><input type="checkbox" checked={supportInternal} onChange={(e)=>setSupportInternal(e.target.checked)}/> Internal staff note</label><button disabled={busy==="support"} className={buttonClass}>{busy==="support"?<Loader2 className="animate-spin" size={17}/>:<Send size={17}/>} {supportInternal?"Save note":"Send reply"}</button></form></>:<p className="text-sm text-slate-500">No ticket selected.</p>}</div></div></Card>

    {isAdmin&&<Card title="User & access management" text="Create a clean separation between Admin, Staff and Client roles." icon={Users}><div className="grid md:grid-cols-2 xl:grid-cols-3 gap-3">{profiles.map(p=><div key={p.id} className="rounded-xl border border-slate-100 dark:border-white/10 p-3"><p className="text-sm font-semibold text-slate-900 dark:text-white">{p.full_name||"Name not set"}</p><p className="text-xs text-slate-500">{p.email}</p><div className="mt-3 grid grid-cols-2 gap-2"><select value={p.role} disabled={p.id===session.user.id||busy===`u-${p.id}`} onChange={(e)=>updateUser(p.id,{role:e.target.value})} className="rounded-lg border border-slate-200 dark:border-white/10 bg-white dark:bg-slate-950 px-2 py-2 text-xs"><option value="client">Client</option><option value="staff">Staff</option><option value="admin">Admin</option></select><select value={p.status} disabled={p.id===session.user.id||busy===`u-${p.id}`} onChange={(e)=>updateUser(p.id,{status:e.target.value})} className="rounded-lg border border-slate-200 dark:border-white/10 bg-white dark:bg-slate-950 px-2 py-2 text-xs"><option value="active">Active</option><option value="inactive">Inactive</option><option value="suspended">Suspended</option></select></div>{memberships.filter(m=>m.user_id===p.id).map(m=><p key={m.id} className="mt-2 text-[11px] text-slate-400">{orgMap[m.organization_id]?.name||m.organization_id} · {label(m.member_role)}</p>)}</div>)}</div></Card>}

    {!isAdmin&&<div className="grid xl:grid-cols-3 gap-6"><Card title="Create project" text="Operational project creation for staff." icon={FolderKanban}><form onSubmit={createStaffProject} className="space-y-3"><select required className={fieldClass} value={staffProject.organization_id} onChange={(e)=>setStaffProject({...staffProject,organization_id:e.target.value})}><option value="">Select client</option>{orgs.filter(o=>o.status==="active").map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select><input required className={fieldClass} value={staffProject.code} onChange={(e)=>setStaffProject({...staffProject,code:e.target.value})} placeholder="Project code"/><input required className={fieldClass} value={staffProject.name} onChange={(e)=>setStaffProject({...staffProject,name:e.target.value})} placeholder="Project name"/><textarea className={fieldClass} rows="2" value={staffProject.summary} onChange={(e)=>setStaffProject({...staffProject,summary:e.target.value})} placeholder="Summary"/><input className={fieldClass} value={staffProject.service_division} onChange={(e)=>setStaffProject({...staffProject,service_division:e.target.value})} placeholder="Service division"/><div className="grid grid-cols-3 gap-2"><input type="date" className={fieldClass} value={staffProject.received_date} onChange={(e)=>setStaffProject({...staffProject,received_date:e.target.value})}/><input type="date" className={fieldClass} value={staffProject.start_date} onChange={(e)=>setStaffProject({...staffProject,start_date:e.target.value})}/><input type="date" className={fieldClass} value={staffProject.due_date} onChange={(e)=>setStaffProject({...staffProject,due_date:e.target.value})}/></div><button className={buttonClass}>Create project</button></form></Card><Card title="Publish project update" text="Updates automatically notify client users." icon={Send}><form onSubmit={postStaffUpdate} className="space-y-3"><select required className={fieldClass} value={staffUpdate.project_id} onChange={(e)=>setStaffUpdate({...staffUpdate,project_id:e.target.value})}><option value="">Select project</option>{projects.map(p=><option key={p.id} value={p.id}>{p.code} — {p.name}</option>)}</select><input required className={fieldClass} value={staffUpdate.title} onChange={(e)=>setStaffUpdate({...staffUpdate,title:e.target.value})} placeholder="Update title"/><textarea required rows="4" className={fieldClass} value={staffUpdate.body} onChange={(e)=>setStaffUpdate({...staffUpdate,body:e.target.value})} placeholder="Update details"/><select className={fieldClass} value={staffUpdate.update_type} onChange={(e)=>setStaffUpdate({...staffUpdate,update_type:e.target.value})}><option value="general">General</option><option value="milestone">Milestone</option><option value="risk">Risk</option><option value="decision">Decision</option><option value="delivery">Delivery</option></select><button className={buttonClass}>Publish update</button></form></Card><Card title="Upload document" text="Staff can publish private client files without administrator access." icon={FileText}><form onSubmit={uploadStaffDoc} className="space-y-3"><select required className={fieldClass} value={staffDocument.organization_id} onChange={(e)=>setStaffDocument({...staffDocument,organization_id:e.target.value,project_id:""})}><option value="">Select client</option>{orgs.map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select><select className={fieldClass} value={staffDocument.project_id} onChange={(e)=>setStaffDocument({...staffDocument,project_id:e.target.value})}><option value="">General / no project</option>{projects.filter(p=>!staffDocument.organization_id||p.organization_id===staffDocument.organization_id).map(p=><option key={p.id} value={p.id}>{p.code} — {p.name}</option>)}</select><input className={fieldClass} value={staffDocument.title} onChange={(e)=>setStaffDocument({...staffDocument,title:e.target.value})} placeholder="Document title"/><select className={fieldClass} value={staffDocument.category} onChange={(e)=>setStaffDocument({...staffDocument,category:e.target.value})}><option value="general">General</option><option value="proposal">Proposal</option><option value="quotation">Quotation</option><option value="invoice">Invoice</option><option value="report">Report</option><option value="design">Design</option><option value="policy">Policy</option><option value="manual">Manual</option><option value="deliverable">Deliverable</option></select><input required type="file" className="text-xs text-slate-500" onChange={(e)=>setStaffDocument({...staffDocument,file:e.target.files?.[0]||null})}/><button className={buttonClass}>Upload document</button></form></Card></div>}
  </div>;
}
